                acc.2.push(conditions.cpu_usage);
                acc.3.push(conditions.memory_usage);
                acc
            },
        );
```

**Optimized version:**

The main inefficiency is using both `filter_map` and `fold`, allocating unreserved vectors, which could be improved for both readability and (possibly) performance. Here’s how I would rewrite it:

```rust
let mut times = Vec::with_capacity(readings.len());
let mut cpu_temperature = Vec::with_capacity(readings.len());
let mut cpu_usage = Vec::with_capacity(readings.len());
let mut memory_usage = Vec::with_capacity(readings.len());

for reading in &readings {
    if let (Some(timestamp), Some(conditions)) = (reading.timestamp.as_ref(), reading.condition.as_ref()) {
        times.push(TimeHelper::to_offset_date_time(timestamp));
        cpu_temperature.push(conditions.cpu_temperature);
        cpu_usage.push(conditions.cpu_usage);
        memory_usage.push(conditions.memory_usage);
    }
}

// If you still want the original tuple destructure:
let (times, cpu_temperature, cpu_usage, memory_usage) = (times, cpu_temperature, cpu_usage, memory_usage);
```

**Explanation:**
- We pre-allocate the vectors with `with_capacity` to reduce possible reallocations. (It’s possible not all readings are present, so we may slightly over-allocate in the worst case.)
- The for-loop is clearer and more direct, with no unnecessary abstraction or closure indirection.
- The result is the same: `times`, `cpu_temperature`, `cpu_usage`, and `memory_usage`, each a Vec of the corresponding values where both timestamp and condition are present.

