    Super::BeginPlay();

    AudioCaptureDevice = FAudioCapture::Create();
    if (AudioCaptureDevice.IsValid())
    {
        IAudioCapture::FCaptureParams Params;
        Params.DeviceIndex = INDEX_NONE; // Default device
        Params.SampleRate = 44100;
        Params.NumChannels = 1; // Mono
        Params.Callback = nullptr; // You may set a callback to process captured data

        if (AudioCaptureDevice->OpenStream(Params))
        {
            AudioCaptureDevice->StartStream();
            UE_LOG(LogTemp, Log, TEXT("Audio capturing started!"));
        }
        else
        {
            UE_LOG(LogTemp, Warning, TEXT("Failed to open audio capture stream."));
        }
    }
    else
