// Helper to highlight quoted text, skipping inside code/pre blocks
function highlightQuotedText(el) {
  for (let child = el.firstChild; child; child = child.nextSibling) {
    // Only process text nodes
    if (child.nodeType === Node.TEXT_NODE) {
      const text = child.textContent;
      // Replace "..." with <span style="color:red">"..."</span>
      // You may want to refine the regex depending on your requirements
      let replaced = text.replace(/"([^"]+)"/g, '<span style="color:red;">"$1"</span>');
      if (replaced !== text) {
        // Replace the text node with HTML
        const temp = document.createElement("span");
        temp.innerHTML = replaced;
        while (temp.firstChild) {
          child.parentNode.insertBefore(temp.firstChild, child);
        }
        child.parentNode.removeChild(child);
      }
    } else if (
      child.nodeType === Node.ELEMENT_NODE &&
      child.tagName !== "CODE" &&
      child.tagName !== "PRE"
    ) {
      // Recursively process non-code elements
      highlightQuotedText(child);
    }
  }
}

