#include <memory>

template <typename T>
struct Node {
    T data;
    std::unique_ptr<Node<T>> next;
    Node(T val) : data(val), next(nullptr) {}
};

template <typename T>
class LinkedList {
    std::unique_ptr<Node<T>> head;
public:
