```rust
use eframe::egui;
use notify::{RecommendedWatcher, RecursiveMode, Watcher, Event, EventKind};
use crossbeam_channel::{unbounded, Receiver};
use std::path::PathBuf;
use std::thread;

struct App {
    input: Option<PathBuf>,
    output: Option<PathBuf>,
    done: Option<PathBuf>,
    logs: Vec<String>,
    watcher_rx: Option<Receiver<notify::Result<Event>>>,
    watcher: Option<RecommendedWatcher>,
}

impl Default for App {
    fn default() -> Self {
        Self {
            input: None,
            output: None,
            done: None,
            logs: vec![],
            watcher_rx: None,
            watcher: None,
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _frame: &mut eframe::Frame) {
        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");

            for (label, dest) in [
                ("Select Input Folder", &mut self.input),
                ("Select Output Folder", &mut self.output),
                ("Select Done Folder", &mut self.done),
            ] {
                ui.horizontal(|ui| {
                    if ui.button(label).clicked() {
                        if let Some(p) = rfd::FileDialog::new().pick_folder() {
                            *dest = Some(p);
                        }
                    }
                    let text = dest.as_ref().map(|p| p.display().to_string()).unwrap_or("None".to_string());
                    ui.label(text);
                });
            }

            if ui.button("Start Monitoring").clicked() {
                if let Some(input_dir) = &self.input {
                    let (tx, rx) = unbounded();
                    let mut watcher = notify::recommended_watcher(move |e| {
                        let _ = tx.send(e);
                    }).unwrap();
                    watcher.watch(input_dir, RecursiveMode::NonRecursive).unwrap();
                    self.watcher_rx = Some(rx);
                    self.watcher = Some(watcher);
                    self.logs.push("Started monitoring.".to_string());
                } else {
                    self.logs.push("Please select an input folder.".to_string());
                }
            }

            if let Some(rx) = &self.watcher_rx {
                while let Ok(Ok(event)) = rx.try_recv() {
                    for path in &event.paths {
                        self.logs.push(format!("Event: {:?} - {:?}", event.kind, path));
                    }
                }
            }

            ui.separator();
            ui.label("Log:");
            egui::ScrollArea::vertical().max_height(200.0).show(ui, |ui| {
                for entry in self.logs.iter().rev().take(100).rev() {
                    ui.label(entry);
                }
            });
        });
        ctx.request_repaint();
    }
}

fn main() {
    let native_options = eframe::NativeOptions::default();
    eframe::run_native(
        "Folder Monitor",
        native_options,
        Box::new(|_cc| Box::new(App::default()))
    );
}
```

