**main.rs Example:**
```rust
use std::path::PathBuf;
use notify::{RecommendedWatcher, RecursiveMode, Watcher, Event};
use crossbeam_channel::{unbounded, Receiver, TryRecvError};

struct App {
    input: Option<PathBuf>,
    output: Option<PathBuf>,
    done: Option<PathBuf>,
    logs: Vec<String>,
    watcher: Option<RecommendedWatcher>,
    rx: Option<Receiver<notify::Result<Event>>>,
    monitoring: bool,
}

impl Default for App {
    fn default() -> Self {
        Self {
            input: None,
            output: None,
            done: None,
            logs: Vec::new(),
            watcher: None,
            rx: None,
            monitoring: false,
        }
    }
}

impl eframe::App for App {
    fn update(&mut self, ctx: &egui::Context, _: &mut eframe::Frame) {
        egui::CentralPanel::default().show(ctx, |ui| {
            ui.heading("Folder Monitor");

            for (label, folder) in [
                ("Input", &mut self.input),
                ("Output", &mut self.output),
                ("Done", &mut self.done)
            ] {
                ui.horizontal(|ui| {
                    if ui.button(format!("Select {} Folder", label)).clicked() {
                        if let Some(path) = rfd::FileDialog::new().pick_folder() {
                            *folder = Some(path);
                        }
                    }
                    ui.label(folder.as_ref().map_or("No folder selected", |p| p.display().to_string().as_str()));
                });
            }

            if ui.button("Start").clicked() && !self.monitoring {
                if let Some(input_path) = &self.input {
                    let (tx, rx) = unbounded();
                    let mut watcher = notify::recommended_watcher(move |res| {
                        let _ = tx.send(res);
                    }).unwrap();
                    watcher.watch(input_path, RecursiveMode::NonRecursive).unwrap();
                    self.rx = Some(rx);
                    self.watcher = Some(watcher);
                    self.monitoring = true;
                    self.logs.push(format!("Started monitoring {}", input_path.display()));
                } else {
                    self.logs.push("Please select an input folder!".to_string());
                }
            }

            // Event Handling
            if let Some(rx) = &self.rx {
                loop {
                    match rx.try_recv() {
                        Ok(Ok(event)) => {
                            if let Some(path) = event.paths.first() {
                                self.logs.push(format!("{} event on {}", format!("{:?}", event.kind), path.display()));
                            }
                        }
                        Ok(Err(e)) => self.logs.push(format!("Error: {e}")),
                        Err(TryRecvError::Empty) => break,
                        Err(TryRecvError::Disconnected) => {
                            self.logs.push("Watcher disconnected".to_string());
                            break;
                        }
                    }
                }
            }

            ui.separator();
            ui.label("Log:");
            egui::ScrollArea::vertical().show(ui, |ui| {
                for log in &self.logs {
                    ui.label(log);
                }
            });
        });
    }
}

fn main() {
    let options = eframe::NativeOptions::default();
    eframe::run_native("Folder Monitor", options, Box::new(|_| Box::new(App::default())));
}
```
