```tsx
import React, { useState, useMemo, useRef, useEffect } from "react";

interface InputProps {
  options: string[];
  placeholder?: string;
}

const Input: React.FC<InputProps> = ({ options, placeholder }) => {
  const [value, setValue] = useState("");
  const [isDropdownVisible, setDropdownVisible] = useState(false);
  const [touched, setTouched] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  // Memoized case-insensitive Set for O(1) validation
  const lowerSet = useMemo(() => new Set(options.map(opt => opt.toLowerCase())), [options]);

  // Debounce filtering for performance
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedValue(value), 200);
    return () => clearTimeout(handler);
  }, [value]);

  // Filter options
  const filtered = useMemo(() => {
    if (!debouncedValue) return [];
    const search = debouncedValue.toLowerCase();
    return options.filter(o => o.toLowerCase().includes(search));
  }, [debouncedValue, options]);

  // Validation
  const isValid = !value || lowerSet.has(value.trim().toLowerCase());

  // Hide dropdown if no match
  useEffect(() => {
    setDropdownVisible(filtered.length > 0 && value.length > 0);
  }, [filtered, value]);

  // Close dropdown on outside click
  useEffect(() => {
    const handleOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setDropdownVisible(false);
        setTouched(true);
      }
    };
    document.addEventListener("mousedown", handleOutside);
    return () => document.removeEventListener("mousedown", handleOutside);
  }, []);

  const selectOption = (option: string) => {
    setValue(option);
    setDropdownVisible(false);
    setTouched(true);
  };

  return (
    <div ref={containerRef} style={{ position: "relative", width: 300 }}>
      <input
        type="text"
        value={value}
        placeholder={placeholder}
        onChange={e => {
          setValue(e.target.value);
          setTouched(true);
        }}
        style={{
          width: "100%",
          padding: 8,
          border: `1px solid ${isValid ? "#ccc" : "red"}`,
          borderRadius: 4,
        }}
      />
      {isDropdownVisible && (
        <ul
          style={{
            position: "absolute",
            width: "100%",
            maxHeight: 200,
            overflowY: "auto",
            zIndex: 10,
            margin: 0,
            padding: 0,
            background: "white",
            border: "1px solid #ccc",
            borderTop: "none",
            listStyle: "none"
          }}
        >
          {filtered.map(option => (
            <li
              key={option}
              style={{
                padding: "8px",
                cursor: "pointer"
              }}
              onMouseDown={() => selectOption(option)}
            >
              {option}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Input;
```

