const std = @import("std");

fn mod_pow(base: u64, exp: u64, modulo: u64) u64 {
    var result: u64 = 1;
    var b = base % modulo;
    var e = exp;
    while (e > 0) : (e /= 2) {
        if ((e & 1) != 0) result = (result * b) % modulo;
        b = (b * b) % modulo;
    }
    return result;
}

pub fn main() !void {
    const allocator = std.heap.page_allocator;
    var file = try std.fs.cwd().openFile("input.txt", .{ .read = true });
    defer file.close();

    var buffer: [256]u8 = undefined;
    const size = try file.readAll(&buffer);
    const input = buffer[0..size];

    // Extract row and col -- look for two numbers in order.
    var numbers: [2]u64 = undefined;
    var count: usize = 0;
    var i: usize = 0;
    while (i < input.len) {
