Below is a C++ code snippet for Ubuntu Linux to control two 5V DC motors through a L298N module. It uses the sysfs GPIO interface, writing directly to /sys/class/gpio. This example assumes your motors are wired such that each motor is controlled by two GPIOs (4 total). Adjust the GPIO numbers according to your wiring.

**No loops are used. Each action is detailed and commented.**

```cpp
#include <fstream>  // For writing to files
#include <unistd.h> // For sleep
#include <iostream> // For error output

int main() {
    // Step 1: Export GPIO pins so they appear in /sys/class/gpio
    std::ofstream exportGPIO("/sys/class/gpio/export");
    exportGPIO << "17";  // Motor 1 Input 1
    exportGPIO.close();

    exportGPIO.open("/sys/class/gpio/export");
    exportGPIO << "18";  // Motor 1 Input 2
    exportGPIO.close();

    exportGPIO.open("/sys/class/gpio/export");
    exportGPIO << "22";  // Motor 2 Input 1
    exportGPIO.close();

    exportGPIO.open("/sys/class/gpio/export");
    exportGPIO << "23";  // Motor 2 Input 2
    exportGPIO.close();

    // Wait for GPIO sysfs to set up files
    sleep(1);

    // Step 2: Set directions to "out"
    std::ofstream dir;
    dir.open("/sys/class/gpio/gpio17/direction");
    dir << "out";
    dir.close();

    dir.open("/sys/class/gpio/gpio18/direction");
    dir << "out";
    dir.close();

    dir.open("/sys/class/gpio/gpio22/direction");
    dir << "out";
    dir.close();

    dir.open("/sys/class/gpio/gpio23/direction");
    dir << "out";
    dir.close();

    // Step 3: Set GPIO values to spin motors forward (change values for other directions)
    std::ofstream val;
    // Motor 1 Forward
    val.open("/sys/class/gpio/gpio17/value");
    val << "1";
    val.close();
    val.open("/sys/class/gpio/gpio18/value");
    val << "0";
    val.close();

    // Motor 2 Forward
    val.open("/sys/class/gpio/gpio22/value");
    val << "1";
    val.close();
    val.open("/sys/class/gpio/gpio23/value");
    val << "0";
    val.close();

    // Step 4: Run motors for 5 seconds
    sleep(5);

    // Step 5: Stop motors (all inputs LOW)
    val.open("/sys/class/gpio/gpio17/value");
    val << "0";
    val.close();
    val.open("/sys/class/gpio/gpio18/value");
    val << "0";
    val.close();
    val.open("/sys/class/gpio/gpio22/value");
    val << "0";
    val.close();
    val.open("/sys/class/gpio/gpio23/value");
    val << "0";
    val.close();

    return 0;
}
```

**Notes:**
- GPIO pins 17,18,22,23 correspond to L298N IN1-IN4. Adjust as needed.
- sudo/root permissions are required.
- No procedural abstraction or loops; every step is explicit.
- EN (enable) pins should be HIGH for motors to work; this code does not manage enable pins.
- Use `g++ -o motor_example motor_example.cpp` to compile, then `sudo ./motor_example` to run.

