```cpp
#include <fstream>   // For writing to GPIO sysfs files
#include <unistd.h>  // For sleep()
#include <string>    // For std::string

int main() {
    // Export each GPIO pin required (Motor 1: 17,18; Motor 2: 22,23)
    std::ofstream gpio_export("/sys/class/gpio/export");
    gpio_export << "17"; gpio_export.close();

    gpio_export.open("/sys/class/gpio/export");
    gpio_export << "18"; gpio_export.close();

    gpio_export.open("/sys/class/gpio/export");
    gpio_export << "22"; gpio_export.close();

    gpio_export.open("/sys/class/gpio/export");
    gpio_export << "23"; gpio_export.close();

    sleep(1); // Give the system time to create GPIO interface

    // Set all exported GPIO as outputs
    std::ofstream gdir;
    gdir.open("/sys/class/gpio/gpio17/direction");
    gdir << "out"; gdir.close();

    gdir.open("/sys/class/gpio/gpio18/direction");
    gdir << "out"; gdir.close();

    gdir.open("/sys/class/gpio/gpio22/direction");
    gdir << "out"; gdir.close();

    gdir.open("/sys/class/gpio/gpio23/direction");
    gdir << "out"; gdir.close();

    // Set the GPIOs for both motors:
    // Motor 1: Forward -> IN1=1, IN2=0 (GPIO17=1, GPIO18=0)
    std::ofstream gval;
    gval.open("/sys/class/gpio/gpio17/value");
    gval << "1"; gval.close();

