This problem is a minimal-cost connectivity problem: Given that there may be several existing connected components (from the existing m roads), the goal is to add the minimum number of roads to make all n houses connected, at minimum total cost, where the cost of a new road between two houses is the sum of their prices.

Approach:
1. Use Disjoint Set Union (Union-Find) to maintain connected components, merging as you process each existing road.
2. For each connected component, find the house with the minimum price (and its index).
3. Among all components, select the globally cheapest house as the "hub".
4. For every other component, connect their cheapest house to the hub. Since you always use the two cheapest (in that case) houses possible, this approach minimizes the cost.
5. Output the roads you add (number and pairs).

If only one component remains after existing roads, print 0.

***Sample C++ Implementation (with explanation inline):***

```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <unordered_map>
#include <climits>
using namespace std;

struct DSU {
    vector<int> p;
    DSU(int n) : p(n) {
        for (int i = 0; i < n; ++i) p[i] = i;
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    void unite(int a, int b) {
        p[find(a)] = find(b);
    }
};

int main() {
    ios::sync_with_stdio(false);
    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];
    DSU dsu(n);
    while (m--) {
        int x, y;
        cin >> x >> y;
        --x; --y;
        dsu.unite(x, y);
    }
    // Find smallest price house in each component
    unordered_map<int, pair<long long, int>> min_house; // root -> {price, idx}
    for (int i = 0; i < n; ++i) {
        int r = dsu.find(i);
        if (!min_house.count(r) || a[i] < min_house[r].first) min_house[r] = {a[i], i};
    }
    if (min_house.size() == 1) {
        cout << "0\n";
        return 0;
    }
    // Find the overall global minimum
    int hub = -1;
    long long hub_price = LLONG_MAX;
    for (auto &p : min_house)
        if (p.second.first < hub_price) {
            hub_price = p.second.first;
            hub = p.second.second;
        }
    // Connect all other comp's min house to hub
    vector<pair<int, int>> roads;
    for (auto &p : min_house)
        if (p.second.second != hub)
            roads.push_back({hub + 1, p.second.second + 1});
    cout << roads.size() << '\n';
    for (auto &pr : roads) cout << pr.first << " " << pr.second << '\n';
    return 0;
}
```
**Explanation:**  
- For each component, connect its cheapest node to the overall cheapest node, minimizing new road costs.
- Output is as required: number of roads followed by the list.


