The problem is essentially: Given an undirected graph (initially possibly disconnected) with n nodes (houses), m edges (existing roads), and a cost for each node. The cost of building a new road between two nodes is the sum of their costs. We are to find a set of new roads so that the graph becomes connected (i.e., there is a path between every pair of nodes) and the total cost is minimized. We need to output the exact roads added.

**High-Level Approach:**

1. Find the connected components using Union-Find (DSU).
2. For each component, identify its node with the minimum cost.
3. Pick the node among all components with the smallest cost, call this node `root`.
4. For every other component, add a road between `root` and the minimum-cost node in that component. This method minimizes the total additional cost (it's the MST on the meta-graph of components with sum-of-nodes as cost).
5. Output the set of new roads added.

**Reference C++ Solution:**

```cpp
#include <iostream>
#include <vector>
#include <unordered_map>
#include <climits>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n+1) {
        for (int i = 1; i <= n; i++) parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        x = find(x); y = find(y);
        if (x != y) parent[y] = x;
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    vector<long long> a(n+1); // 1-based
    for (int i=1; i<=n; ++i) cin >> a[i];
    DSU dsu(n);

    for (int i=0; i<m; ++i) {
        int u, v;
        cin >> u >> v;
        dsu.unite(u, v);
    }
    unordered_map<int, pair<long long,int>> min_node; // comp_root -> (min_a, node)
    for (int i=1; i<=n; ++i) {
        int root = dsu.find(i);
        if (min_node.find(root)==min_node.end() || a[i]<min_node[root].first)
            min_node[root]={a[i],i};
    }
    if (min_node.size()==1) {
        cout << "0\n";
        return 0;
    }
    // Find global minimum
    long long gmin=LLONG_MAX; int gnode=-1, grot=-1;
    for (auto& p : min_node)
        if (p.second.first<gmin) { gmin=p.second.first; gnode=p.second.second; grot=p.first; }
    vector<pair<int,int>> edges;
    for (auto& p : min_node)
        if (p.first!=grot) edges.push_back({gnode, p.second.second});
    cout << edges.size() << '\n';
    for (auto& e : edges) cout << e.first << ' ' << e.second << '\n';
}
```

**Explanation:**

- We use Union-Find to find all connected components.
- For each component, we remember its cheapest house.
- The best strategy is to connect all other components to the component whose cheap house is the global minimum.
- This requires adding k-1 roads, where k = number of components.
- The cost is always minimized since you're always pairing the global cheapest house with each other component's cheapest.

