To allow a character to move along a cube, sphere, or custom surface in Unity 2023, with proper rotation to follow surface normals, follow these steps:

**1. Surface Normal Alignment**
- Cast a ray down from the character in the direction of 'gravity' (or use -transform.up if your character walks anywhere).
- Read the hit.normal from the RaycastHit and use it to align the character’s up.

**2. Input and Movement**
- Capture the input vector.
- Project movement onto the tangent of the hit surface (using Vector3.ProjectOnPlane).

**3. Rotation**
- Smoothly rotate the character so its 'up' matches the surface normal.

**4. Implementation Example (with Rigidbody):**

```csharp
using UnityEngine;

public class SurfaceWalker : MonoBehaviour
{
    public float moveSpeed = 5f;
    public float rotationSpeed = 10f;
    public float gravityStrength = 10f;
    public float rayDistance = 2f;
    private Rigidbody rb;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        rb.freezeRotation = true;
    }

    void FixedUpdate()
    {
        RaycastHit hit;
        if (Physics.Raycast(transform.position, -transform.up, out hit, rayDistance))
        {
            Vector3 normal = hit.normal;
            Quaternion targetRot = Quaternion.FromToRotation(transform.up, normal) * transform.rotation;
            transform.rotation = Quaternion.Slerp(transform.rotation, targetRot, rotationSpeed * Time.deltaTime);

            float h = Input.GetAxis("Horizontal");
            float v = Input.GetAxis("Vertical");
            Vector3 input = new Vector3(h, 0, v);
            Vector3 direction = Vector3.ProjectOnPlane(transform.TransformDirection(input), normal).normalized;

            rb.velocity = direction * moveSpeed + (-normal * gravityStrength);
        }
        else
        {
            rb.AddForce(Physics.gravity, ForceMode.Acceleration);
        }
    }
}
```
- Place Rigidbody and a collider on your character.
- Adjust `rayDistance` based on character height.

