To allow a character to move across any surface (cube, sphere, custom mesh) while aligning its rotation to the surface normal in Unity 2023, you typically:

1. **Detect the Surface Under the Character:** Use a Physics.Raycast (or SphereCast for robustness) from the character's position downwards (opposite its 'up' direction) to determine the nearest point of contact and get the surface normal.

2. **Align the Character to the Surface Normal:** Calculate and smoothly interpolate the character's rotation so its 'up' vector matches the surface normal.

3. **Project Movement Along the Surface:** When moving the character (in FixedUpdate for physics correctness), make sure the movement is projected onto the tangent of the surface (so movement hugs curves, slopes, etc.), by projecting intended movement vectors onto the plane defined by the local surface normal.

**Example C# Script** (Rigidbody method, attach to character with Rigidbody and Collider):

```csharp
using UnityEngine;

public class SurfaceWalker : MonoBehaviour
{
    public float moveSpeed = 5f;
    public float rotationSpeed = 8f;
    public float raycastDistance = 1.2f;
    public float stickGravity = 20f; // adds "sticky" force to surface

    Rigidbody rb;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        rb.freezeRotation = true;
    }

    void FixedUpdate()
    {
        // 1. Raycast down from current position/opposite current up
        if (Physics.Raycast(transform.position, -transform.up, out RaycastHit hit, raycastDistance))
        {
            Vector3 normal = hit.normal;

            // 2. Align up vector to surface normal smoothly
            Quaternion targetRot = Quaternion.FromToRotation(transform.up, normal) * transform.rotation;
            transform.rotation = Quaternion.Slerp(transform.rotation, targetRot, rotationSpeed * Time.fixedDeltaTime);

            // 3. Get input and move along the surface
            float h = Input.GetAxis("Horizontal");
            float v = Input.GetAxis("Vertical");

            Vector3 input = new Vector3(h, 0, v);
            if (input.sqrMagnitude > 0.01f)
            {
                // Handle move relative to object or camera as desired!
                input = transform.TransformDirection(input);

                // Project onto surface tangent plane
                Vector3 moveDir = Vector3.ProjectOnPlane(input, normal).normalized * moveSpeed;
                rb.velocity = moveDir - normal * stickGravity; // "stick" to surface
            }
            else
            {
                rb.velocity = -normal * stickGravity; // just stick in place
            }
        }
        else
        {
            // Not grounded: fall with default gravity, or could keep last normal briefly
            rb.AddForce(Physics.gravity, ForceMode.Acceleration);
        }
    }
}
```

