#include <QCoreApplication>
#include <QXlsx/xlsxdocument.h>
#include <QSet>
#include <QString>
#include <QVariant>
#include <QDebug>
#include <cmath>

bool parseNumericString(const QString &s, int &out) {
    QString str = s.trimmed().toLower();
    bool ok = false;
    if (str.startsWith("0x")) {
        out = str.mid(2).toInt(&ok, 16);
    } else if (str.startsWith("0b")) {
        // No builtin base-2 support, parse manually:
        out = 0;
        for (int i = 2; i < str.size(); ++i) {
            if (str[i] == '0' || str[i] == '1') {
                out = out * 2 + (str[i] == '1' ? 1 : 0);
            } else {
                return false;
            }
        }
        ok = true;
    } else if (str.startsWith("0") && str.size() > 1) {
        out = str.toInt(&ok, 8);
    } else {
        out = str.toInt(&ok, 10);
    }
    return ok;
}

bool cellContainsAllowedNumber(const QVariant &cellValue) {
    static const QSet<int> allowed = {0,1,2,3,10,11,42};

    bool ok = false;
    int value = 0;

    // Check if it's a number
    double d = cellValue.toDouble(&ok);
    if (ok) {
        if (std::floor(d) == d) {
            value = static_cast<int>(d);
            return allowed.contains(value);
        } else {
            return false;
        }
    }
    // Check if it's a string
    if (cellValue.type() == QVariant::String) {
        QString s = cellValue.toString();
        if (parseNumericString(s, value))
            return allowed.contains(value);
        // Strings like "10.0" should also count as 10
        bool floatOk = false;
        double df = s.toDouble(&floatOk);
        if (floatOk && std::floor(df) == df) {
            value = static_cast<int>(df);
            return allowed.contains(value);
        }
    }
    // Any other type is not allowed
    return false;
}

int main(int argc, char *argv[]) {
    QCoreApplication app(argc, argv);

    QString path = "filename.xlsx";
    QString cell = "A1";

    QXlsx::Document xlsx(path);
    if (!xlsx.load()) {
        qWarning() << "Failed to load file";
        return 1;
    }

    QVariant val = xlsx.read(cell);
    if (!val.isValid()) {
        qWarning() << "Invalid cell";
        return 1;
    }

    if (cellContainsAllowedNumber(val))
        qDebug() << "Cell is valid";
    else
        qDebug() << "Cell is NOT valid";

    return 0;
