**AudioRecorderViewModel.swift**
```swift
import Foundation
import AVFoundation
import Combine

class AudioRecorderViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var audioPower: Float = -160 // dB scale

    private var audioRecorder: AVAudioRecorder?
    private var meteringTimer: Timer?
    private var recordingURL: URL?

    func startRecording() {
        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] allowed in
            guard let self = self else { return }
            if allowed {
                DispatchQueue.main.async {
                    self.setupRecorderAndStart()
                }
            } else {
                // Handle denial (show UI, etc.)
            }
        }
    }

    private func setupRecorderAndStart() {
        let file = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString + ".m4a")
        let settings = [
            AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
            AVSampleRateKey: 12000,
            AVNumberOfChannelsKey: 1,
            AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
        ]
        do {
            try AVAudioSession.sharedInstance().setCategory(.playAndRecord, mode: .default)
            try AVAudioSession.sharedInstance().setActive(true)

            let recorder = try AVAudioRecorder(url: file, settings: settings)
            recorder.isMeteringEnabled = true
            recorder.prepareToRecord()
            recorder.record()
            audioRecorder = recorder
            recordingURL = file
            isRecording = true

            meteringTimer = Timer.scheduledTimer(withTimeInterval: 0.07, repeats: true) { [weak self] _ in
                self?.updateAudioPower()
            }
        } catch {
            // Handle error
        }
    }

    private func updateAudioPower() {
        audioRecorder?.updateMeters()
        audioPower = audioRecorder?.averagePower(forChannel: 0) ?? -160
    }

    func stopRecording() {
        audioRecorder?.stop()
        isRecording = false
        meteringTimer?.invalidate()
        meteringTimer = nil
    }
}
```

