### 1. **Audio Recording Logic (ViewModel)**

```swift
import Foundation
import AVFoundation
import Combine

class AudioRecorderViewModel: ObservableObject {
    @Published var isRecording = false
    @Published var powerLevel: Float = -60 // in dB
    @Published var recordingURL: URL? = nil

    private var audioRecorder: AVAudioRecorder?
    private var meterTimer: Timer?

    // Returns recording URL in Documents directory
    private func recordingURL() -> URL {
        let fileName = "recording_\(Int(Date().timeIntervalSince1970)).m4a"
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        return docs.appendingPathComponent(fileName)
    }

    func startRecording() {
        AVAudioSession.sharedInstance().requestRecordPermission { [weak self] granted in
            guard let self = self else { return }
            guard granted else {
                // Handle if needed
                return
            }
            DispatchQueue.main.async {
                do {
                    let session = AVAudioSession.sharedInstance()
                    try session.setCategory(.playAndRecord, mode: .default)
                    try session.setActive(true)

                    let settings: [String: Any] = [
                        AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                        AVSampleRateKey: 12000,
                        AVNumberOfChannelsKey: 1,
                        AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
                    ]

                    let url = self.recordingURL()
                    self.audioRecorder = try AVAudioRecorder(url: url, settings: settings)
                    self.audioRecorder?.isMeteringEnabled = true
                    self.audioRecorder?.record()
                    self.isRecording = true
                    self.recordingURL = nil // reset
                    self.startMetering()
                } catch {
                    print("Failed to start recording: \(error)")
                }
            }
        }
    }

    func stopRecording() {
        audioRecorder?.stop()
        meterTimer?.invalidate()
        if let url = audioRecorder?.url {
            recordingURL = url
        }
        audioRecorder = nil
        isRecording = false
    }

    private func startMetering() {
        meterTimer = Timer.scheduledTimer(withTimeInterval: 0.1, repeats: true) { [weak self] _ in
            guard let self = self else { return }
            self.audioRecorder?.updateMeters()
            self.powerLevel = self.audioRecorder?.averagePower(forChannel: 0) ?? -60
        }
    }

    deinit {
        meterTimer?.invalidate()
    }
}
```

