### 2. **Equalizer View**

```swift
import SwiftUI

struct EqualizerView: View {
    var dbLevel: Float
    var isActive: Bool

    func normalizedPower(_ level: Float) -> CGFloat {
        // dB range: roughly -60 (silence) to 0 (loud)
        let minDb: Float = -60
        let clamped = max(minDb, min(level, 0))
        return CGFloat((clamped - minDb) / abs(minDb))
    }

    let barNum = 6

    var body: some View {
        HStack(spacing: 6) {
            ForEach(0..<barNum, id: \.self) { idx in
                // Add some randomness for animation look
                let normalized = normalizedPower(dbLevel)
                let dynamic = normalized * CGFloat(.random(in: 0.7...1.0)) * 100 + 10
                RoundedRectangle(cornerRadius: 3)
                    .fill(isActive ? Color.blue : Color.gray)
                    .frame(width: 10, height: isActive ? dynamic : 10)
                    .animation(.linear(duration: 0.1), value: dbLevel)
            }
        }
        .frame(height: 120)
    }
}
```

