        trainB1 -> valB1 [label="Evaluate"];
        trainB2 -> valB2 [label="Evaluate"];
        trainB3 -> valB3 [label="Evaluate"];
    }

    // Flows
    split -> hyperA;
    split -> hyperB;
    hyperA -> trainA1;
    hyperA -> trainA2;
    hyperA -> trainA3;
    hyperB -> trainB1;
    hyperB -> trainB2;
