export interface UserCreationPayload { /* fill as needed */ }
export interface PermissionPayload { /* fill as needed */ }
export interface UserCredentials {
  username: string;
  password: string;
}

export class UserService {
  constructor(private readonly request: APIRequestContext) {}

  async createUser(payload: UserCreationPayload): Promise<{ id: string }> {
    const res = await this.request.post('/users/v2/create', { data: payload });
    if (res.status() !== 201) throw new Error("User creation failed");
    return await res.json();
  }

  async updatePermissions(id: string, permPayload: PermissionPayload): Promise<UserCredentials> {
    const res = await this.request.post('/users/v2/permissions', { data: { ...permPayload, id } });
    if (res.status() !== 200) throw new Error("Permission update failed");
    return await res.json();
  }

  async createAdminUser(
    createPayload: UserCreationPayload, 
    permPayload: PermissionPayload
  ): Promise<UserCredentials> {
    const { id } = await this.createUser(createPayload);
    return await this.updatePermissions(id, permPayload);
  }
}


// loginPage.ts
import { Page } from '@playwright/test';

export class LoginPage {
  constructor(private page: Page) {}
  async login(username: string, password: string) {
    await this.page.fill('#username', username);
    await this.page.fill('#password', password);
    await this.page.click('#loginButton');
  }
}


