// userApi.ts
import { APIRequestContext } from '@playwright/test';

export interface UserPayload { /* ... user creation fields ... */ }
export interface PermissionPayload { /* ... permission fields ... */ }
export interface UserCredentials { username: string; password: string; }

export class UserApi {
  constructor(private request: APIRequestContext) {}

  async createUser(payload: UserPayload): Promise<string> {
    const res = await this.request.post('/users/v2/create', { data: payload });
    if (res.status() !== 201) throw new Error('User creation failed');
    const data = await res.json();
    return data.id;
  }

  async updatePermissions(userId: string, permissions: PermissionPayload): Promise<UserCredentials> {
    const res = await this.request.post('/users/v2/permissions', { data: { ...permissions, id: userId } });
    if (res.status() !== 200) throw new Error('Permission update failed');
    return res.json();
  }
}

// userFactory.ts
import { APIRequestContext } from '@playwright/test';
import { UserApi, UserPayload, PermissionPayload, UserCredentials } from './userApi';

export class UserFactory {
  private api: UserApi;
  constructor(request: APIRequestContext) {
    this.api = new UserApi(request);
  }

  async createAdminUser(userPayload: UserPayload, permissionPayload: PermissionPayload): Promise<UserCredentials> {
    const userId = await this.api.createUser(userPayload);
    return this.api.updatePermissions(userId, permissionPayload);
  }
}

// loginPage.ts
import { Page } from '@playwright/test';
export class LoginPage {
  constructor(private page: Page) {}
  async login(username: string, password: string) {
    await this.page.fill('#username', username);
    await this.page.fill('#password', password);
    await this.page.click('#loginButton');
  }
}

// user.spec.ts
