import { UserFactory } from './userFactory';
import { LoginPage } from './loginPage';

test('Create admin user and login', async ({ request, page }) => {
  const userFactory = new UserFactory(request);
  const loginPage = new LoginPage(page);

  const userPayload = { /* ... fields */ };
  const permissionPayload = { /* ... fields */ };

  const creds = await userFactory.createAdminUser(userPayload, permissionPayload);

  await loginPage.login(creds.username, creds.password);

  // Further assertions...
});
