      let input = steps[current].querySelector('input');
      if (input.value === '') { alert('Please fill the field.'); return; }
      showStep(current+1);
    };
  });
  document.querySelectorAll('.back-btn').forEach(btn => {
    btn.onclick = () => {
      showStep(current-1);
    };
  });
});
