To implement an infinite scrolling table in Vue 3 using Pinia and JavaScript (not TypeScript), with a fixed table header and dynamic row loading via a REST API with `start` and `count` parameters, follow the steps below:

**1. Create the Pinia Store**

```javascript
// stores/tableStore.js
import { defineStore } from 'pinia';
import { ref } from 'vue';

export const useTableStore = defineStore('tableStore', () => {
  const rows = ref([]);
  const isLoading = ref(false);
  const start = ref(0);
  const count = 20;
  const hasMore = ref(true);

  async function loadMoreRows() {
    if (isLoading.value || !hasMore.value) return;

    isLoading.value = true;
    try {
      // Replace this URL with your actual endpoint
      const resp = await fetch(
        `https://api.example.com/rows?start=${start.value}&count=${count}`
      );
      const arr = await resp.json();

      if (!arr.length || arr.length < count) {
        hasMore.value = false;
      }
      rows.value.push(...arr);
      start.value += arr.length;
    } catch (e) {
      console.error('Failed to load rows', e);
    } finally {
      isLoading.value = false;
    }
  }

  return { rows, isLoading, hasMore, loadMoreRows };
});
```

