class FoobarArticleTeaserListBlock extends BlockBase implements ContainerFactoryPluginInterface {

  /** @var \Drupal\Core\Entity\EntityTypeManagerInterface */
  protected $entityTypeManager;

  public function __construct(array $configuration, $plugin_id, $plugin_definition, EntityTypeManagerInterface $entity_type_manager) {
    parent::__construct($configuration, $plugin_id, $plugin_definition);
    $this->entityTypeManager = $entity_type_manager;
  }

  public static function create(ContainerInterface $container, array $configuration, $plugin_id, $plugin_definition) {
    return new static(
      $configuration,
      $plugin_id,
      $plugin_definition,
      $container->get('entity_type.manager')
    );
  }

  public function build() {
    // 1. Look up the term ID for 'foobar'.
    $terms = $this->entityTypeManager
      ->getStorage('taxonomy_term')
      ->loadByProperties(['name' => 'foobar']);
    if (empty($terms)) {
      return ['#markup' => $this->t('No matching articles found.')];
    }
    $term = reset($terms);

    // 2. Query for published article nodes tagged with 'foobar'.
    $query = $this->entityTypeManager
      ->getStorage('node')
      ->getQuery()
      ->condition('status', 1)
      ->condition('type', 'article')
      ->condition('field_tags.target_id', $term->id())
      ->sort('created', 'DESC')
      ->range(0, 10);
    $nids = $query->execute();

    if (empty($nids)) {
      return ['#markup' => $this->t('No matching articles found.')];
    }

    // 3. Load nodes and render in "teaser" view mode.
    $nodes = $this->entityTypeManager->getStorage('node')->loadMultiple($nids);
    $view_builder = $this->entityTypeManager->getViewBuilder('node');
    $teasers = [];
    foreach ($nodes as $node) {
      // Wrap each teaser in list-group-item.
      $teasers[] = [
        '#type' => 'container',
        '#attributes' => ['class' => ['list-group-item']],
        'content' => $view_builder->view($node, 'teaser'),
      ];
    }

    // 4. Return Bootstrap 5 styled list group.
    return [
      '#type' => 'container',
      '#attributes' => ['class' => ['list-group']],
      'items' => $teasers,
      '#attached' => [
        // Ensure Bootstrap 5 is available.
        'library' => [
          'my_module/bootstrap5', // Replace with real library if needed.
        ],
      ],
      '#cache' => [
        'tags' => [
          'node_list:article',
          'taxonomy_term:' . $term->id(),
        ],
      ],
    ];
  }
}
