```cpp
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
using namespace std;

// Add two big integers as strings
string bigAdd(const string &a, const string &b) {
    int i = a.size()-1, j = b.size()-1, carry = 0;
    string result;
    while (i >= 0 || j >= 0 || carry) {
        int digit = carry;
        if (i >= 0) digit += a[i--] - '0';
        if (j >= 0) digit += b[j--] - '0';
        result.push_back('0' + digit % 10);
        carry = digit / 10;
    }
    reverse(result.begin(), result.end());
    return result;
}

// Compare two big integers as strings
int bigCompare(const string &a, const string &b) {
    if (a.size() != b.size()) return (a.size() > b.size() ? 1 : -1);
    return (a == b ? 0 : (a > b ? 1 : -1));
}

int main() {
    int n;
    cin >> n;
    vector<string> a(n), b(n);

    for (int i = 0; i < n; ++i) cin >> a[i];
    for (int i = 0; i < n; ++i) cin >> b[i];

    string sumA = "0", sumB = "0";
    for (int i = 0; i < n; ++i) sumA = bigAdd(sumA, a[i]);
    for (int i = 0; i < n; ++i) sumB = bigAdd(sumB, b[i]);

