```cpp
#include <Wire.h>
#include <Adafruit_SSD1306.h>
#include <Adafruit_GFX.h>
#include <RTClib.h>

#define OLED_ADDR 0x3C
Adafruit_SSD1306 display(128, 64, &Wire, -1);

RTC_DS3231 rtc;

#define TV_LIVING_PIN 5
#define TV_BED_PIN 6
#define NIGHT_BUTTON 4

unsigned long SIM_FACTOR = 6; // 6:1 time acceleration, user changeable
unsigned long simStartMillis;
unsigned long simStartSec = 6 * 3600; // Model clock starts at 06:00
bool night_short = false;

void setup() {
  pinMode(TV_LIVING_PIN, OUTPUT);
  pinMode(TV_BED_PIN, OUTPUT);
  pinMode(NIGHT_BUTTON, INPUT_PULLUP);

  Wire.begin();
  rtc.begin();
  display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR);
  display.clearDisplay();

  simStartMillis = millis();
}

void loop() {
  // Calculate accelerated "model time"
  unsigned long realElapsed = millis() - simStartMillis;
  unsigned long modelSeconds = simStartSec + (realElapsed / 1000UL) * SIM_FACTOR;
  modelSeconds %= 86400UL;

  // Event scheduling
  const unsigned long MORNING_TV_START = 6*3600, MORNING_TV_END = 7*3600;
  const unsigned long EVENING_TV_START = 19*3600, EVENING_TV_END = 20*3600;
  const unsigned long NIGHT_TV_START = 22*3600;
  unsigned long NIGHT_TV_DURATION = digitalRead(NIGHT_BUTTON) ? 3600 : 2*3600;
  unsigned long NIGHT_TV_END = NIGHT_TV_START + NIGHT_TV_DURATION;

  // Outputs control and event labels
  String event = "None";
  analogWrite(TV_BED_PIN, 0); analogWrite(TV_LIVING_PIN, 0);

  if (modelSeconds >= MORNING_TV_START && modelSeconds < MORNING_TV_END) {
    analogWrite(TV_BED_PIN, random(64,255)); event="Morning TV";
  } else if (modelSeconds >= EVENING_TV_START && modelSeconds < EVENING_TV_END) {
    analogWrite(TV_LIVING_PIN, random(64,255)); event="Evening TV";
  } else if (modelSeconds >= NIGHT_TV_START && modelSeconds < NIGHT_TV_END) {
    analogWrite(TV_BED_PIN, random(64,255)); event="Bedtime TV";
  }

  // Display
  display.clearDisplay();
  display.setCursor(0,0);
  display.setTextSize(2);
  display.print("Time: ");
  int hh = modelSeconds/3600, mm = (modelSeconds%3600)/60;
  display.printf("%02d:%02d\n", hh, mm);
  display.setTextSize(1);
  display.print("Event: "); display.println(event);
  display.display();

  delay(100); // smooth update
}
```
