**我的标准答案**

题目要求给定一个列表的矩形，计算所有矩形叠加的总面积（被重复覆盖的区域算一次），结果取 $10^9+7$ 的模。矩形的坐标范围很大（$10^9$），但矩形数量最多50。

最优解法：
- 使用扫描线算法。
- 扫描线沿x轴前进，每遇到一个竖边时，用线段树或差分数组实时维护y轴被覆盖的长度。
- 对所有矩形的y1、y2离散化，然后根据事件（矩形左边入，右边出）动态维护覆盖计数。
- 每前进一段x距离，累加dx * 当前y方向总被覆盖长度。
- 最终结果取模。

**C++代码（线段树+扫描线，带离散化）：**
```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
const int MOD = 1e9+7;

struct Event {
    int x, y1, y2, type;
    Event(int _x, int _y1, int _y2, int _type) : x(_x), y1(_y1), y2(_y2), type(_type) {}
    bool operator < (const Event &e) const { return x < e.x; }
};

struct SegmentTree {
    int n;
    vector<int> cnt;
    vector<ll> len;
    vector<int> ys;
    SegmentTree(const vector<int> &_ys) : ys(_ys) {
        n = ys.size()-1;
        cnt.resize(n*4);
        len.resize(n*4);
    }
    void update(int L, int R, int v, int l, int r, int k) {
        if(R <= l || r <= L) return;
        if(L <= l && r <= R) {
            cnt[k] += v;
        } else {
            int m = (l+r)/2;
            update(L, R, v, l, m, k*2);
            update(L, R, v, m, r, k*2+1);
        }
        if(cnt[k]>0) {
            len[k] = ys[r]-ys[l];
        } else if(r-l==1) {
            len[k] = 0;
        } else {
            len[k] = len[k*2]+len[k*2+1];
        }
    }
};

int main() {
    int n;
    cin >> n;
    vector<vector<int>> recs(n, vector<int>(4));
    vector<int> yto;
    vector<Event> evs;
    for(int i=0;i<n;++i) {
        int x1, y1, x2, y2;
        cin >> x1 >> y1 >> x2 >> y2;
        recs[i][0]=x1;
        recs[i][1]=y1;
        recs[i][2]=x2;
        recs[i][3]=y2;
        yto.push_back(y1); yto.push_back(y2);
    }
    sort(yto.begin(), yto.end());
    yto.erase(unique(yto.begin(), yto.end()), yto.end());

    for(int i=0;i<n;++i) {
        int x1=recs[i][0], y1=recs[i][1], x2=recs[i][2], y2=recs[i][3];
        int id1=lower_bound(yto.begin(), yto.end(), y1)-yto.begin();
        int id2=lower_bound(yto.begin(), yto.end(), y2)-yto.begin();
        evs.emplace_back(x1, id1, id2, 1);
        evs.emplace_back(x2, id1, id2, -1);
    }
    sort(evs.begin(), evs.end());
    SegmentTree seg(yto);
    ll ans=0;
    int prevx=evs[0].x;
    for(const auto &e:evs) {
        int dx=e.x-prevx;
        ans=(ans+seg.len[1]*dx%MOD)%MOD;
        seg.update(e.y1, e.y2, e.type, 0, seg.n, 1);
        prevx=e.x;
    }
    cout<<ans<<endl;
    return 0;
}
```
此算法复杂度 $O(n^2)$，但对于$n=50$足够快。

