【题目分析与解题思路】
本题需要计算多个大坐标范围、轴对齐矩形的总覆盖面积（即并集面积），并对 $10^9+7$ 取模。矩形叠加区间面积可用「扫描线+线段树+离散化」来解决。

具体步骤如下：
- 把每个矩形转化为两个事件：(x1, [y1, y2), +1) 和 (x2, [y1, y2), -1)；
- 收集所有 y1/y2，排序去重，离散化；
- 扫描 x 轴事件，用线段树维护 y 方向的覆盖总长度，累加每个区间的面积。
- 注意：线段树节点存储 区间覆盖次数 及当前区间被覆盖的长度。

【参考 C++ 实现代码（伪代码，重难点详解）】：

```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1e9+7;

struct Event {
    ll x;
    int y1, y2;
    int type; // +1 (矩形起点), -1 (矩形终点)
};

struct SegmentTree {
    int n;
    vector<int> count;
    vector<ll> len;
    vector<ll> ys;

    SegmentTree(const vector<ll>& ys_) : ys(ys_) {
        n = ys.size() - 1;
        count.assign(4*n, 0);
        len.assign(4*n, 0);
    }

    void update(int node, int l, int r, int ql, int qr, int val) {
        if (qr <= l || ql >= r) return;
        if (ql <= l && r <= qr) {
            count[node] += val;
        } else {
            int m = (l+r)/2;
            update(2*node, l, m, ql, qr, val);
            update(2*node+1, m, r, ql, qr, val);
        }
        if (count[node] > 0) len[node] = ys[r] - ys[l];
        else if (r-l == 1) len[node] = 0;
        else len[node] = len[2*node] + len[2*node+1];
    }
};

int main() {
    int n;
    cin >> n;
    vector<vector<ll>> rects(n, vector<ll>(4));
    vector<Event> events;
    vector<ll> ys;
    for (int i = 0; i < n; ++i) {
        cin >> rects[i][0] >> rects[i][1] >> rects[i][2] >> rects[i][3];
        events.push_back(Event{rects[i][0], (int)rects[i][1], (int)rects[i][2], 1});
        events.push_back(Event{rects[i][2], (int)rects[i][1], (int)rects[i][2], -1});
        ys.push_back(rects[i][1]);
        ys.push_back(rects[i][3]);
    }
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    sort(events.begin(), events.end(), [](const Event& a, const Event& b) { return a.x < b.x; });

    SegmentTree seg(ys);
    ll res = 0, preX = events[0].x;
    for (auto& e : events) {
        ll x = e.x;
        res = (res + ((x-preX) % MOD) * (seg.len[1] % MOD)) % MOD;
        int l = lower_bound(ys.begin(), ys.end(), e.y1) - ys.begin();
        int r = lower_bound(ys.begin(), ys.end(), e.y2) - ys.begin();
        seg.update(1, 0, seg.n, l, r, e.type);
        preX = x;
    }
    cout << res << endl;
    return 0;
}
```

