```shader
Shader "Custom/ExtrudedTexturePixels"
{
    Properties
    {
        _MainTex ("Texture (with Alpha)", 2D) = "white" {}
        _AlphaThreshold ("Alpha Threshold", Range(0,1)) = 0.1
        _Extrude ("Extrude Factor", Float) = 0.1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            CGPROGRAM
            #pragma target 4.0
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float4 _MainTex_TexelSize;
            float _AlphaThreshold;
            float _Extrude;

            struct appdata
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 pos : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 pos : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.pos = UnityObjectToClipPos(v.vertex); // or just v.vertex if pre-transformed
                o.uv = v.uv;
                return o;
            }

            [maxvertexcount(6)]
            void geom(point v2g IN[1], inout TriangleStream<g2f> triStream)
            {
                float4 col = tex2D(_MainTex, IN[0].uv);
                if (col.a < _AlphaThreshold)
                    return;

                // Compute quad size based on texture texel size, or custom size
                float2 quadHalfSize = _MainTex_TexelSize.xy * 0.5;

                // Base pos in object space or world space (before UnityObjectToClipPos)
                float3 basePos = IN[0].pos.xyz; // May need to convert from clip space

                float3 extrudeDir = float3(0, 0, _Extrude);

                // Create four corners of the quad
                float3 corners[4];
                corners[0] = basePos + float3(-quadHalfSize.x, -quadHalfSize.y, 0); // BL
                corners[1] = basePos + float3(quadHalfSize.x, -quadHalfSize.y, 0);  // BR
                corners[2] = basePos + float3(quadHalfSize.x, quadHalfSize.y, 0) + extrudeDir; // TR extruded
                corners[3] = basePos + float3(-quadHalfSize.x, quadHalfSize.y, 0) + extrudeDir; // TL extruded

                float2 uvs[4];
                uvs[0] = IN[0].uv;
                uvs[1] = IN[0].uv;
                uvs[2] = IN[0].uv;
                uvs[3] = IN[0].uv;

                // Emit two triangles (BL, BR, TR) and (TR, TL, BL)
                g2f outVert;
                outVert.uv = IN[0].uv;

                // First triangle
                outVert.pos = UnityObjectToClipPos(float4(corners[0], 1));
                triStream.Append(outVert);
                outVert.pos = UnityObjectToClipPos(float4(corners[1], 1));
                triStream.Append(outVert);
                outVert.pos = UnityObjectToClipPos(float4(corners[2], 1));
                triStream.Append(outVert);

                // Second triangle
                outVert.pos = UnityObjectToClipPos(float4(corners[2], 1));
                triStream.Append(outVert);
                outVert.pos = UnityObjectToClipPos(float4(corners[3], 1));
                triStream.Append(outVert);
                outVert.pos = UnityObjectToClipPos(float4(corners[0], 1));
                triStream.Append(outVert);
            }

            fixed4 frag(g2f i) : SV_Target
            {
                return tex2D(_MainTex, i.uv);
            }
            ENDCG
        }
    }
}
```

