  unsubscribe(eventName, callback) {
    if (!this.subscribers[eventName]) return;
    this.subscribers[eventName] = this.subscribers[eventName].filter(cb => cb !== callback);
  }

  // Trigger one or more events (eventNames can be string/array), optional arguments spread to callbacks
  trigger(eventNames, ...options) {
    if (typeof eventNames === "string") {
      eventNames = [eventNames];
    }
    for (const eventName of eventNames) {
      if (this.subscribers[eventName]) {
        // use slice in case the list is modified in a callback
        this.subscribers[eventName].slice().forEach(cb => cb(...options));
      }
    }
  }
}

