可以采用递归+回溯的方法，代码如下：

```java
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class StaircaseWays {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        System.out.print("请输入台阶数n: ");
        int n = scanner.nextInt();
        scanner.close();

        List<List<Integer>> allWays = new ArrayList<>();
        findWays(n, new ArrayList<>(), allWays);

        System.out.println("总共有 " + allWays.size() + " 种走法：");
        for (List<Integer> way : allWays) {
            System.out.println(way);
        }
    }

    private static void findWays(int remain, List<Integer> path, List<List<Integer>> res) {
        if (remain == 0) {
            res.add(new ArrayList<>(path));
            return;
        }
        if (remain >= 1) {
            path.add(1);
            findWays(remain - 1, path, res);
            path.remove(path.size() - 1);
        }
        if (remain >= 2) {
            path.add(2);
            findWays(remain - 2, path, res);
            path.remove(path.size() - 1);
        }
    }
}
```

