### 思路分析

题目问的是：给定 a, b 两个整数，以及它们在某一进制 k 下的不进位加法结果 c，求有多少个不同的正整数 k ≥ 2 能满足这个式子。如果有无穷多个这样的k，输出-1。

- 无进位加法定义：把 a/b/c 都写成 k 进制，每个对应位无进位相加对 k 取模。
- 数学转化：**a+b-c 必须能够被 k 整除**，否则不存在这样的 M 满足 a+b = c + k*M
- 如果 a+b–c < 0, 不存在解, 输出0。
- 如果 a+b–c == 0，等价于 a+b==c。此时只需找到最小k满足所有进位都不会超出。实际上“所有足够大的k都可行”——无限多个，输出-1。
- 否则（d>0），所有的 k≥2 且为 d 的因数的 k，均为可能候选，然后要模拟k进制下 a,b,c，看是否满足 (a%k+b%k)%k==c%k，依此对所有位验证。

### 伪代码：

```
for each test (a,b,c):
  d = a+b-c
  if d < 0: print 0
  else if d == 0: print -1
  else:
    ans = 0
    for 每个 d 的因子 k (k>=2):
      if 所有进制下都满足 (a_i+b_i)%k==c_i:
        ans += 1
    print ans
```

### C++ 实现

```cpp
#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

bool is_valid(long long a, long long b, long long c, long long k) {
    while(a > 0 || b > 0 || c > 0) {
        long long da = a % k;
        long long db = b % k;
        long long dc = c % k;
        if ((da + db) % k != dc) return false;
        a /= k; b /= k; c /= k;
    }
    return true;
}

int main() {
    int T; cin >> T;
    while (T--) {
        long long a, b, c;
        cin >> a >> b >> c;
        long long d = a+b-c;
        if (d < 0) {
            cout << 0 << endl;
        } else if (d == 0) {
            cout << -1 << endl;
        } else {
            int ans = 0;
            for (long long k = 2; k*k <= d; ++k) {
                if (d % k == 0) {
                    if (is_valid(a,b,c,k)) ans++;
                    if (k != d/k && d/k >= 2 && is_valid(a,b,c,d/k)) ans++;
                }
            }
            if (d >= 2 && is_valid(a,b,c,d)) ans++;
            cout << ans << endl;
        }
    }
    return 0;
}
```

