bool check(long long a, long long b, long long c, long long k) {
    while (a > 0 || b > 0 || c > 0) {
        int da = a % k, db = b % k, dc = c % k;
        if (((da + db) % k) != dc) return false;
        a /= k;
        b /= k;
        c /= k;
    }
    return true;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        long long a, b, c;
