        } else if (d == 0) {
            cout << -1 << endl;
        } else {
            int cnt = 0;
            for (long long i = 1; i * i <= d; ++i) {
                if (d % i == 0) {
                    if (i >= 2 && check(a, b, c, i)) cnt++;
                    long long j = d / i;
                    if (j != i && j >= 2 && check(a, b, c, j)) cnt++;
                }
            }
            cout << cnt << endl;
        }
    }
    return 0;
}
